78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    /**
104	     * The owner's locality, i.e. the canonical region it belongs to (read from the
105	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
106	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
107	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
108	     * full derivation.
109	     *
110	     * @return the canonical region string, or {@code "UNKNOWN"}
111	     */
112	    @Transient
113	    public String getLocality() {
114	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
115	    }
116	
117	    /**
118	     * The canonical region derived for this owner from its own fields. Recomputed each
119	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
120	     *
121	     * @return the canonical region string, or {@code "UNKNOWN"}
122	     */
123	    public String regionForOwner() {
124	        return OwnerDerivations.region(this.postcode, this.city);
125	    }
126	
127	    /**
128	     * Whether this owner's postcode is consistent with its {@link #getLocality()
129	     * locality}: an absent postcode is accepted, a present one must be exactly four
130	     * digits and, when the locality has a known postcode range, fall within it. See
131	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
132	     *
133	     * @return {@code true} if the postcode is absent or valid for the owner's locality
134	     */
135	    public boolean postcodeValidForLocality() {
136	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
137	    }
138	
139	    /**
140	     * The owner's membership level, a number from 1 to 3. Derived (not persisted);
141	     * recomputed from the current fields each call. See
142	     * {@link OwnerDerivations#membershipLevel(String, Integer)} for how it is assigned.
143	     *
144	     * @return the membership level, from 1 to 3
145	     */
146	    @Transient
147	    public Integer getMembershipLevel() {
148	        return OwnerDerivations.membershipLevel(this.email, this.namesakeCount);
149	    }
150	
151	    /**
152	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
153	     * Derived (not persisted); recomputed from the current fields each call. See
154	     * {@link OwnerDerivations#contactPreference(String)}.
155	     *
156	     * @return {@code "EMAIL"} or {@code "PHONE"}
157	     */
158	    @Transient
159	    public String getContactPreference() {
160	        return OwnerDerivations.contactPreference(this.email);
161	    }
162	
163	    public String getTelephone() {
164	        return this.telephone;
165	    }
166	
167	    public void setTelephone(String telephone) {
168	        this.telephone = telephone;
169	    }
170	
171	    public String getEmail() {
172	        return this.email;
173	    }
174	
175	    public void setEmail(String email) {
176	        this.email = email;
177	    }
178	
179	    public String getPostcode() {
180	        return this.postcode;
181	    }
182	
183	    public void setPostcode(String postcode) {
184	        this.postcode = postcode;
185	    }
186	
