196	        return this.birthDate;
197	    }
198	
199	    public void setBirthDate(LocalDate birthDate) {
200	        this.birthDate = birthDate;
201	    }
202	
203	    /**
204	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
205	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
206	     * Derived (not persisted); recomputed each call and {@code null} when no birth
207	     * date has been supplied. See
208	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
209	     *
210	     * @return the age band, or {@code null} when no birth date is present
211	     */
212	    @Transient
213	    public String getAgeBand() {
214	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
215	    }
216	
217	    public String getCustomerCode() {
218	        return this.customerCode;
219	    }
220	
221	    public void setCustomerCode(String customerCode) {
222	        this.customerCode = customerCode;
223	    }
224	
225	    /**
226	     * The Luhn check digit (0-9) computed over the digits in this owner's
227	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
228	     * {@link OwnerDerivations#checkDigit(String)}.
229	     *
230	     * @return the Luhn check digit, from 0 to 9
231	     */
