277	    /**
278	     * The derived key used for duplicate detection, combining this owner's normalised
279	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
280	     * their whole identity keys are equal, so members of the same household with
281	     * different telephones have different keys. Derived (not persisted); recomputed each
282	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
283	     * exact format.
284	     *
285	     * @return the owner's identity key
286	     */
287	    @Transient
288	    public String getIdentityKey() {
289	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
290	    }
291	
292	    /**
293	     * A stable, normalised key identifying this owner's household (same last name
294	     * and address). The last name is folded case- and whitespace-insensitively and
295	     * the address is reduced to its canonical form exactly as in
296	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
297	     * household.
298	     *
299	     * @return the household key
300	     */
301	    public String householdKey() {
302	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
303	    }
304	
305	    /**
306	     * Whether this owner belongs to the same household as {@code other}: that is,
307	     * they share the same last name and address. The last name is compared
308	     * case-insensitively with runs of whitespace collapsed to a single space (and
309	     * surrounding whitespace trimmed); the address is compared in its canonical
310	     * normalised form (see {@link #normalizeAddress(String)}).
311	     *
312	     * @param other the owner to compare against
313	     * @return {@code true} if both owners share a household
314	     */
315	    public boolean sameHouseholdAs(Owner other) {
316	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
317	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
318	    }
319	
320	    /**
321	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
322	     * trim, collapse internal runs of whitespace to a single space and lower-case.
323	     */
324	    private static String normalize(String value) {
325	        if (value == null) {
326	            return "";
327	        }
328	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
329	    }
330	
331	    /**
332	     * Reduce an address to its canonical stored form: trim and collapse runs of
333	     * whitespace to a single space, upper-case, and expand common abbreviations
334	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
335	     * they appear as whole words. The result is what is stored, returned and used
336	     * for every household comparison; it is idempotent, so re-normalising an
337	     * already-normalised address leaves it unchanged.
338	     *
339	     * @param value the raw address (may be {@code null})
340	     * @return the normalised address, or the empty string if {@code value} is
341	     *         {@code null} or blank
342	     */
343	    public static String normalizeAddress(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
348	        if (collapsed.isEmpty()) {
349	            return "";
350	        }
351	        String[] tokens = collapsed.split(" ");
352	        for (int i = 0; i < tokens.length; i++) {
353	            tokens[i] = switch (tokens[i]) {
354	                case "ST" -> "STREET";
355	                case "RD" -> "ROAD";
356	                case "AVE" -> "AVENUE";
357	                default -> tokens[i];
358	            };
359	        }
360	        return String.join(" ", tokens);
361	    }
362	
363	    protected Set<Pet> getPetsInternal() {
364	        if (this.pets == null) {
365	            this.pets = new HashSet<>();
366	        }
367	        return this.pets;
368	    }
369	
370	    protected void setPetsInternal(Set<Pet> pets) {
371	        this.pets = pets;
372	    }
373	
374	    public List<Pet> getPets() {
375	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
376	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
377	        return Collections.unmodifiableList(sortedPets);
378	    }
379	
380	    public void setPets(List<Pet> pets) {
381	        this.pets = new HashSet<>(pets);
382	    }
383	
384	    public void addPet(Pet pet) {
385	        getPetsInternal().add(pet);
386	        pet.setOwner(this);
387	    }
388	
389	    /**
390	     * Return the Pet with the given name, or null if none found for this Owner.
391	     *
392	     * @param name to test
393	     * @return true if pet name is already in use
394	     */
395	    public Pet getPet(String name) {
396	        return getPet(name, false);
397	    }
398	
399	    /**
400	     * Return the Pet with the given name, or null if none found for this Owner.
401	     *
402	     * @param name to test
403	     * @return true if pet name is already in use
404	     */
405	    public Pet getPet(String name, boolean ignoreNew) {
406	        name = name.toLowerCase();
407	        for (Pet pet : getPetsInternal()) {
408	            if (!ignoreNew || !pet.isNew()) {
409	                String compName = pet.getName();
410	                compName = compName.toLowerCase();
411	                if (compName.equals(name)) {
412	                    return pet;
413	                }
414	            }
415	        }
416	        return null;
417	    }
418	
419	    public Pet getPet(Integer petId) {
420	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
421	    }
422	
423	    @Override
424	    public String toString() {
425	        return new ToStringCreator(this)
426	
427	            .append("id", this.getId())
428	            .append("new", this.isNew())
429	            .append("lastName", this.getLastName())
430	            .append("firstName", this.getFirstName())
431	            .append("address", this.address)
432	            .append("city", this.city)
433	            .append("telephone", this.telephone)
434	            .toString();
435	    }
436	}
