57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (!normalizeNewOwner(owner)) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (dailyLimitReached(owner.getRegistrationDate())) {
118	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
119	        }
120	        if (cityIsAtCapacity(owner.getCity())) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        Optional<Owner> householdMember = findHouseholdMember(owner);
124	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
125	            joinHousehold(owner, householdMember.get());
126	        }
127	        if (identityKeyAlreadyUsed(owner)) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        owner.setCustomerCode(customerCode(owner));
131	        owner.setNamesakeCount(countNamesakes(owner));
132	        owner.setMembershipNumber(membershipNumber(owner));
133	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
134	        owner.setHouseholdSize(householdSize(owner));
135	        this.clinicService.saveOwner(owner);
136	        auditOwnerCreated(owner);
137	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
138	        headers.setLocation(UriComponentsBuilder.newInstance()
139	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
140	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
146	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
147	        if (currentOwner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        currentOwner.setAddress(ownerFieldsDto.getAddress());
151	        currentOwner.setCity(ownerFieldsDto.getCity());
152	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
153	        currentOwner.setLastName(ownerFieldsDto.getLastName());
154	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
155	        String email = ownerFieldsDto.getEmail();
156	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        this.clinicService.deleteOwner(owner);
170	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        HttpHeaders headers = new HttpHeaders();
181	        Pet pet = petMapper.toPet(petFieldsDto);
182	        owner.setId(ownerId);
183	        pet.setOwner(owner);
184	        pet.getType().setName(null);
185	        this.clinicService.savePet(pet);
186	        PetDto petDto = petMapper.toPetDto(pet);
187	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
188	            .buildAndExpand(pet.getId()).toUri());
189	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner != null) {
197	            Pet currentPet = this.clinicService.findPetById(petId);
198	            if (currentPet != null) {
199	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
200	                currentPet.setName(petFieldsDto.getName());
201	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
202	                this.clinicService.savePet(currentPet);
203	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	            }
205	        }
206	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
212	        HttpHeaders headers = new HttpHeaders();
213	        Visit visit = visitMapper.toVisit(visitFieldsDto);
214	        Pet pet = new Pet();
215	        pet.setId(petId);
216	        visit.setPet(pet);
217	        this.clinicService.saveVisit(visit);
218	        VisitDto visitDto = visitMapper.toVisitDto(visit);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
220	            .buildAndExpand(visit.getId()).toUri());
221	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
222	    }
223	
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner != null) {
230	            Pet pet = owner.getPet(petId);
231	            if (pet != null) {
232	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    /**
239	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
240	     * the canonical form each stored value must take: the address is trimmed,
241	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
242	     * telephone is converted to E.164, any email is lower-cased and a missing
243	     * registration date defaults to today. Field-level rejections are reported here
244	     * rather than inline in {@link #addOwner}, and normalisation runs before any
245	     * household comparison so those comparisons see the canonical values.
246	     *
247	     * @param owner the freshly-mapped owner to normalise
248	     * @return {@code true} if the fields are valid, or {@code false} if the address
249	     *         is blank after normalisation, the telephone cannot form a valid
250	     *         E.164 number, or a supplied registration date is later than the
251	     *         server date, in which case the request must be rejected with
252	     *         {@code 400 Bad Request}
253	     */
254	    private boolean normalizeNewOwner(Owner owner) {
255	        String address = Owner.normalizeAddress(owner.getAddress());
256	        if (address.isEmpty()) {
257	            return false;
258	        }
259	        owner.setAddress(address);
260	        String telephone = toE164(owner.getTelephone());
261	        if (telephone == null) {
262	            return false;
263	        }
264	        owner.setTelephone(telephone);
265	        if (owner.getEmail() != null) {
266	            owner.setEmail(owner.getEmail().toLowerCase());
267	        }
268	        if (!owner.postcodeValidForLocality()) {
269	            return false;
270	        }
271	        if (owner.getRegistrationDate() == null) {
272	            owner.setRegistrationDate(LocalDate.now());
273	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
274	            return false;
275	        }
276	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
277	        return true;
278	    }
279	
280	    /**
281	     * Roll the given date forward to the next business day when it falls on a
282	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
283	     * weekday is returned unchanged. Applied to the effective registration date
284	     * (whether supplied in the request or defaulted to the server date) so that
285	     * every value derived from it uses the adjusted business day.
286	     *
287	     * @param date the effective registration date
288	     * @return the same date if it is a weekday, otherwise the next Monday
289	     */
290	    private static LocalDate rollToBusinessDay(LocalDate date) {
291	        switch (date.getDayOfWeek()) {
292	            case SATURDAY:
293	                return date.plusDays(2);
294	            case SUNDAY:
295	                return date.plusDays(1);
296	            default:
297	                return date;
298	        }
299	    }
300	
301	    /**
302	     * Determine whether the candidate owner's identity key collides with any existing
303	     * owner's. This is the single, consolidated duplicate check: it subsumes the
304	     * former separate telephone, email and household checks by comparing the whole
305	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
306	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
307	     * that agree on some — but not all — of the key's parts (for example two members of
308	     * the same household with different telephones) are not duplicates. Evaluated after
309	     * normalisation and household resolution, so the candidate's key reflects its
310	     * canonical field values and any household it has joined.
311	     *
312	     * @param owner the candidate owner being created, after household resolution
313	     * @return {@code true} if an existing owner has the same identity key
314	     */
315	    private boolean identityKeyAlreadyUsed(Owner owner) {
316	        String identityKey = owner.getIdentityKey();
317	        return this.clinicService.findAllOwners().stream()
318	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
319	    }
320	
321	    /**
322	     * Find an existing owner that belongs to the same household as the given owner,
323	     * i.e. shares the same last name and address (compared case-insensitively with
324	     * runs of whitespace collapsed to a single space).
325	     *
326	     * @param owner the candidate owner being created
327	     * @return the matching existing owner, or empty if none exists
328	     */
329	    private Optional<Owner> findHouseholdMember(Owner owner) {
330	        return this.clinicService.findAllOwners().stream()
331	            .filter(existing -> existing.sameHouseholdAs(owner))
332	            .findFirst();
333	    }
334	
335	    /**
336	     * Assign the joining owner and an existing household member the same stable
337	     * household identifier. The identifier is derived deterministically from the
338	     * shared household key (last name + address, normalised), so every owner in a
339	     * household resolves to the same value; the existing member is updated when it
340	     * does not already carry it.
341	     *
342	     * @param owner    the owner being created
343	     * @param existing an existing owner in the same household
344	     */
345	    private void joinHousehold(Owner owner, Owner existing) {
346	        String householdId = UUID
347	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
348	        owner.setHouseholdId(householdId);
349	        if (!householdId.equals(existing.getHouseholdId())) {
350	            existing.setHouseholdId(householdId);
351	            this.clinicService.saveOwner(existing);
352	        }
353	    }
354	
355	    /**
356	     * Count how many owners belong to the given owner's household once this create
357	     * completes: the owners that already share its {@code householdId} plus the owner
358	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
359	     * so the household identifier (and any existing member updated to it) is already in
360	     * place. An owner that has not joined a household (no {@code householdId}) is a
361	     * household of one.
362	     *
363	     * @param owner the candidate owner being created, after household resolution
364	     * @return the household member count after this create (at least {@code 1})
365	     */
366	    private int householdSize(Owner owner) {
367	        String householdId = owner.getHouseholdId();
368	        if (householdId == null) {
369	            return 1;
370	        }
371	        long existing = this.clinicService.findAllOwners().stream()
372	            .filter(other -> householdId.equals(other.getHouseholdId()))
373	            .count();
374	        return (int) existing + 1;
375	    }
376	
377	    /**
378	     * Count the existing owners that share the given owner's first and last name,
379	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
380	     * before the new owner is saved, so the result reflects only owners that
381	     * already existed at creation time.
382	     *
383	     * @param owner the candidate owner being created
384	     * @return the number of existing namesakes
385	     */
386	    private int countNamesakes(Owner owner) {
387	        String firstName = normalizeName(owner.getFirstName());
388	        String lastName = normalizeName(owner.getLastName());
389	        return (int) this.clinicService.findAllOwners().stream()
390	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
391	                && normalizeName(existing.getLastName()).equals(lastName))
392	            .count();
393	    }
394	
395	    private static String normalizeName(String value) {
396	        return value == null ? "" : value.trim().toLowerCase();
397	    }
398	
399	    /**
400	     * Determine whether the given city has already reached its owner capacity, i.e.
401	     * it already contains 50 or more existing owners (compared case-insensitively
402	     * with surrounding whitespace trimmed). A new owner may not be created in a city
403	     * that is at capacity.
404	     *
405	     * @param city the candidate owner's city
406	     * @return {@code true} if the city already holds 50 or more owners
407	     */
408	    private boolean cityIsAtCapacity(String city) {
409	        String normalizedCity = normalizeName(city);
410	        long count = this.clinicService.findAllOwners().stream()
411	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
412	            .count();
413	        return count >= 50;
414	    }
415	
416	    /**
417	     * Determine whether the daily owner-creation limit has already been reached, i.e.
418	     * 100 or more owners already carry the given registration date. A new owner may
419	     * not be created once that day's cap is reached.
420	     *
421	     * @param registrationDate the registration date the new owner would be created with
422	     * @return {@code true} if 100 or more existing owners share that registration date
423	     */
424	    private boolean dailyLimitReached(LocalDate registrationDate) {
425	        long count = this.clinicService.findAllOwners().stream()
426	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
427	            .count();
428	        return count >= 100;
429	    }
430	
431	    /**
432	     * Determine whether more than 80 owners have already been created for the given
433	     * registration date, i.e. strictly more than 80 existing owners carry that date.
434	     * Evaluated before the new owner is saved, so it reflects only owners that
435	     * already existed at creation time.
436	     *
437	     * @param registrationDate the registration date the new owner would be created with
438	     * @return {@code true} if more than 80 existing owners share that registration date
439	     */
440	    private boolean bulkSignupWarning(LocalDate registrationDate) {
441	        long count = this.clinicService.findAllOwners().stream()
442	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
443	            .count();
444	        return count > 80;
445	    }
446	
447	    /**
448	     * Build the customer code assigned to the given owner, formatted
449	     * {@code <REGION>-<HASH8>}: REGION is the canonical region derived for the owner
450	     * (see {@link Owner#regionForOwner()}, the postcode-then-city region also exposed
451	     * as its {@link Owner#getLocality() locality}) and HASH8 is the first eight
452	     * upper-case hexadecimal characters of the SHA-256 digest of the owner's
453	     * normalised telephone concatenated with its last name (e.g.
454	     * {@code NSW-9F86D081}). The whole owner is passed so the code can be derived from
455	     * whichever of its (already normalised) fields the identity scheme requires.
456	     *
457	     * @param owner the owner being created, with its fields already normalised
458	     * @return the assigned customer code
459	     */
460	    private String customerCode(Owner owner) {
461	        String region = owner.regionForOwner();
462	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
463	        return String.format("%s-%s", region, hash8);
464	    }
465	
466	    /**
467	     * The first eight upper-case hexadecimal characters of the SHA-256 digest of the
468	     * UTF-8 bytes of the given value.
469	     */
470	    private static String sha256Hex8(String value) {
471	        try {
472	            byte[] digest = MessageDigest.getInstance("SHA-256")
473	                .digest(value.getBytes(StandardCharsets.UTF_8));
474	            StringBuilder hex = new StringBuilder();
475	            for (byte b : digest) {
476	                hex.append(String.format("%02X", b));
477	                if (hex.length() >= 8) {
478	                    break;
479	                }
480	            }
481	            return hex.substring(0, 8);
482	        } catch (NoSuchAlgorithmException e) {
483	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
484	        }
485	    }
486	
487	    /**
488	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
489	     * one place so it stays in step with the owner's identity: it reports the assigned
490	     * customer code alongside the owner's id, registration date and membership level.
491	     *
492	     * @param owner the owner that has just been created and saved
493	     */
494	    private void auditOwnerCreated(Owner owner) {
495	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
496	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
497	    }
498	
499	    /**
500	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
501	     * where {@code <customerCode>} is the owner's already-assigned customer code and
502	     * YY is the last two digits of the registration date's year (e.g.
503	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
504	     * have been set.
505	     *
506	     * @param owner the owner being created, with customer code and registration date
507	     *              already assigned
508	     * @return the assigned membership number
509	     */
510	    private String membershipNumber(Owner owner) {
511	        int yy = owner.getRegistrationDate().getYear() % 100;
512	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
513	    }
514	
515	    /**
516	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
517	     * code when present, otherwise assume country code '+61' and drop a single
518	     * leading '0' from the national digits. Spaces, dashes and brackets are
519	     * stripped. The result must contain 8 to 15 digits after the '+'.
520	     *
521	     * <p>In addition, the national-number length is validated against the country
522	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
523	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
524	     * whose national-number length is wrong for its country code is rejected.
525	     *
526	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
527	     *         input cannot form a valid E.164 number.
528	     */
529	    private static String toE164(String raw) {
530	        if (raw == null) {
531	            return null;
532	        }
533	        String cleaned = raw.replaceAll("[\\s()-]", "");
534	        String digits;
535	        if (cleaned.startsWith("+")) {
536	            digits = cleaned.substring(1);
537	        } else {
538	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
539	            digits = "61" + national;
540	        }
541	        if (!digits.matches("\\d{8,15}")) {
542	            return null;
543	        }
544	        if (!nationalNumberLengthValid(digits)) {
545	            return null;
546	        }
547	        return "+" + digits;
548	    }
549	
550	    /**
551	     * Validate the length of the national number (the digits after the country
552	     * code) against the country code carried by the given E.164 digit string: a
553	     * {@code 61} (Australia) number requires exactly 9 national digits and a
554	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
555	     * without a pinned length are accepted (only the generic 8-15 digit rule
556	     * applies to them).
557	     *
558	     * @param digits the E.164 digits without the leading '+'
559	     * @return {@code true} if the national-number length is correct for the country
560	     */
561	    private static boolean nationalNumberLengthValid(String digits) {
562	        if (digits.startsWith("61")) {
563	            return digits.length() - 2 == 9;
564	        }
565	        if (digits.startsWith("1")) {
566	            return digits.length() - 1 == 10;
567	        }
568	        return true;
569	    }
570	}
